package com.example.starter.support;

import java.time.Clock;
import java.time.LocalDateTime;
import java.time.ZoneId;

import org.springframework.stereotype.Component;

/**
 * 应用时钟：生产环境使用 Asia/Shanghai 系统时钟；测试可替换为固定时钟以控制时间相关判定。
 */
@Component
public class AppClock {

    /** 业务时区：Asia/Shanghai。 */
    public static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");

    private volatile Clock clock = Clock.system(ZONE);

    /**
     * 返回当前本地时间（Asia/Shanghai）。
     */
    public LocalDateTime now() {
        return LocalDateTime.now(clock);
    }

    /**
     * 替换底层时钟，仅供测试使用。
     */
    public void setClock(Clock clock) {
        this.clock = clock;
    }

    /**
     * 恢复为系统时钟。
     */
    public void reset() {
        this.clock = Clock.system(ZONE);
    }
}

package com.example.starter.web;

/**
 * 业务冲突异常：映射为 HTTP 409，用于同键异参幂等冲突、非法状态流转等场景。
 */
public class ConflictException extends RuntimeException {

    public ConflictException(String message) {
        super(message);
    }
}

package com.example.starter.web;

/**
 * 资源不存在异常：映射为 HTTP 404。
 */
public class NotFoundException extends RuntimeException {

    public NotFoundException(String message) {
        super(message);
    }
}

package com.example.starter.web;

import java.util.Map;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 全局异常映射：业务冲突返回 409，资源不存在返回 404。
 */
@RestControllerAdvice
public class ApiExceptionHandler {

    @ExceptionHandler(ConflictException.class)
    public ResponseEntity<Map<String, String>> conflict(ConflictException ex) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error", ex.getMessage()));
    }

    @ExceptionHandler(NotFoundException.class)
    public ResponseEntity<Map<String, String>> notFound(NotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(Map.of("error", ex.getMessage()));
    }
}

