package com.example.starter.web.dto;

import java.time.LocalDateTime;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 故障接报请求。reportedAt 为空时由服务端取当前时间；importantUser 为空表示不涉及重要用户。
 *
 * @param requestId     幂等请求号
 * @param feederId      馈线编号
 * @param faultPoint    故障点
 * @param affectedUsers 影响用户数
 * @param importantUser 重要用户名称（合成数据），可为空
 * @param reportedAt    接报时间，可为空
 */
public record FaultReportRequest(
        @NotBlank String requestId,
        @NotBlank String feederId,
        @NotBlank String faultPoint,
        @NotNull @Min(0) Integer affectedUsers,
        String importantUser,
        LocalDateTime reportedAt) {
}

package com.example.starter.web.dto;

import java.time.LocalDateTime;

/**
 * 故障接报响应。
 *
 * @param reportId    接报记录ID
 * @param workOrderId 关联工单ID
 * @param status      工单当前状态
 * @param merged      是否按“故障点+时段”归并到既有接报
 * @param replayed    是否为同键同参幂等重放
 * @param reportedAt  接报时间
 */
public record FaultReportResponse(
        long reportId,
        long workOrderId,
        String status,
        boolean merged,
        boolean replayed,
        LocalDateTime reportedAt) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 派单请求。
 *
 * @param requestId   幂等请求号
 * @param workOrderId 工单ID
 * @param teamId      目标班组ID
 */
public record DispatchRequest(
        @NotBlank String requestId,
        @NotNull Long workOrderId,
        @NotNull Long teamId) {
}

package com.example.starter.web.dto;

import java.math.BigDecimal;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 复电确认请求。role 取 DISPATCHER（调度）或 FIELD（现场）；现场确认必须携带恢复负荷 loadKw。
 *
 * @param requestId   幂等请求号
 * @param workOrderId 工单ID
 * @param role        确认角色：DISPATCHER/FIELD
 * @param confirmer   确认人
 * @param loadKw      恢复负荷，单位kW；现场角色必填
 */
public record RestoreConfirmRequest(
        @NotBlank String requestId,
        @NotNull Long workOrderId,
        @NotBlank String role,
        @NotBlank String confirmer,
        BigDecimal loadKw) {
}

package com.example.starter.web.dto;

import java.util.List;

import jakarta.validation.constraints.NotEmpty;

/**
 * 工单合并请求：将多张同馈线工单合并为一张新工单。
 *
 * @param sourceOrderIds 被合并的源工单ID列表，至少两张
 */
public record MergeRequest(@NotEmpty List<Long> sourceOrderIds) {
}

package com.example.starter.web.dto;

import java.util.List;

/**
 * 工单合并响应。
 *
 * @param newOrderId     合并生成的新工单ID
 * @param sourceOrderIds 被合并的源工单ID列表
 */
public record MergeResponse(long newOrderId, List<Long> sourceOrderIds) {
}

